import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { OracleLogService, LogEntry } from './oracle-log.service'; // ◄ ייבוא ה-LogEntry המתוקן

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  errors: LogEntry[] = []; // ◄ מערך מסוג ה-Proto שלכם
  statusMessage = 'ממתין לפקודה...';
  statusClass = '';
  isLoaded = false;

  constructor(private logService: OracleLogService) {}

  ngOnInit() {
    this.loadErrors();
  }

  loadErrors() {
    this.statusMessage = 'טוען נתונים מהשרת... ⏳';
    this.statusClass = 'status-loading';
    
    this.logService.getCriticalErrors().subscribe({
      next: (response) => {
        // ◄ חילוץ המערך מתוך ה-Response. ודא שבחרת בשם השדה שמופיע ב-Swagger (למשל logs)
        this.errors = response.logs || []; 
        this.isLoaded = true;
        this.statusMessage = `📊 נטענו ${this.errors.length} שורות לוג בהצלחה`;
        this.statusClass = 'status-success';
      },
      error: (err) => {
        console.error('כשל בשליפת נתונים באנגולר:', err);
        this.statusMessage = 'שגיאת תקשורת ❌';
        this.statusClass = 'status-error';
        this.errors = [];
      }
    });
  }
}
<h1>📋 לוח בקרה: שגיאות קריטיות במערכת Oracle</h1>

<div class="control-panel">
  <button class="refresh-btn" (click)="loadErrors()">רענן נתונים מחדש 🔄</button>
  <span class="status-badge" [ngClass]="statusClass">{{ statusMessage }}</span>
</div>

<table>
  <thead>
    <tr>
      <th>מזהה שגיאה (ID)</th>
      <th>רמת חומרה (Level)</th>
      <th>תוכן הודעת השגיאה (Message)</th>
      <th>זמן אירוע (Time)</th>
    </tr>
  </thead>
  <tbody>
    @if (errors.length > 0) {
      @for (log of errors; track log.id) {
        <tr>
          <td class="error-id">{{ log.id }}</td>
          <td>
            <!-- צביעה דינמית קלה לפי רמת השגיאה (אופציונלי) -->
            <span [style.color]="log.level === 'CRITICAL' ? '#b91c1c' : '#334155'" style="font-weight: bold;">
              {{ log.level }}
            </span>
          </td>
          <td>{{ log.message }}</td>
          <td>{{ log.time }}</td>
        </tr>
      }
    } @else {
      <tr>
        <td colspan="4" class="no-data">
          {{ isLoaded ? '✅ לא נמצאו שגיאות קריטיות בלוגים!' : 'אין נתונים להצגה כעת. לחץ רענן.' }}
        </td>
      </tr>
    }
  </tbody>
</table>
